// generated by eider
export interface EiderExports {
  i32_neg(v: number): number;
  i64_twice(v: bigint): bigint;
  u8_next(v: number): number;
  u32_max(): number;
  u64_big(v: bigint): bigint;
  usize_len(n: bigint): bigint;
  not(b: boolean): boolean;
  mixed(a: number, b: bigint, c: boolean): bigint;
  nothing(v: number): void;
}
export interface EiderImports { [name: string]: (...args: any[]) => any }
export function load(wasm: BufferSource | WebAssembly.Module, imports?: EiderImports): Promise<EiderExports>;
